run_era5_mintemp_pipeline <- function(config_path="config/era5_mintemp.yml",mode=c("diagnose","plan","download","process","aggregate","estimate","full"),dry_run=TRUE,observed_end=NULL,future_end=NULL,output_root=NULL,overwrite=FALSE,rebuild_all_weeks=FALSE,execution_source="default") {
  mode<-match.arg(mode); root<-resolve_project_root(dirname(config_path)); cfg<-read_pipeline_config(config_path); cfg<-resolve_config_paths(cfg,root,output_root,FALSE); if(!is.null(observed_end)) cfg$temporal$observed_end<-as.Date(observed_end); if(!is.null(future_end)) cfg$temporal$future_end_date<-as.Date(future_end); cfg<-validate_pipeline_config(cfg); storage<-resolve_storage_paths(cfg,root,output_root,create=TRUE); cfg$project_root<-root; m<-initialize_run_manifest(cfg,mode,dry_run,execution_source); invd<-inventory_grid_directory(storage$daily_dir,cfg$project$output_prefix,"daily",TRUE); invw<-inventory_grid_directory(storage$weekly_dir,cfg$project$output_prefix,"weekly",TRUE); diag<-diagnose_spatial_domain(cfg$spatial$template_path,cfg$spatial$bbox_path,cfg); if(mode%in%c("diagnose","plan","full","download")) { plan<-plan_observed_update(invd,cfg$temporal$initial_start_date,cfg$temporal$observed_end,cfg$temporal$overlap_days); req<-build_era5_mintemp_requests(plan$date,diag$proposed_cds_area,cfg); write_cds_request_manifests(req,m$run_dir); utils::write.csv(plan,file.path(m$run_dir,"planned_dates.csv"),row.names=FALSE); utils::write.csv(compress_dates_to_intervals(plan$date),file.path(m$run_dir,"planned_intervals.csv"),row.names=FALSE); utils::write.csv(invd,file.path(m$run_dir,"inventory_daily.csv"),row.names=FALSE); utils::write.csv(invw,file.path(m$run_dir,"inventory_weekly.csv"),row.names=FALSE); jsonlite::write_json(diag,file.path(m$run_dir,"spatial_diagnostics.json"),pretty=TRUE,auto_unbox=TRUE); if((mode=="download"||mode=="full")&&!dry_run) { if(!requireNamespace("ecmwfr",quietly=TRUE)) stop("Package 'ecmwfr' is required for CDS download execution.",call.=FALSE); if(!nzchar(Sys.getenv("ecmwfr_PAT"))) stop("ecmwfr_PAT is unavailable to R. Set it in ~/.Renviron or export it before submission.",call.=FALSE); download_cds_requests(req,storage$raw_dir,m$run_dir,FALSE,overwrite,cfg$cds$batch_workers) } } else plan<-data.frame(); if(mode%in%c("aggregate","full")&&!dry_run) aggregate_daily_to_weekly(storage$daily_dir,storage$weekly_dir,cfg$project$output_prefix,overwrite=TRUE,template_path=cfg$spatial$template_path,rebuild_all=rebuild_all_weeks); finalize_run_manifest(m,"success")
}
